package com.dispatchpro.driver;
import android.app.job.*;
import android.content.*;
import android.os.Build;
/** Short FCM wake/resync, no permanent customer background polling. */
public final class MobileSyncJob extends JobService {
 private final java.util.concurrent.ConcurrentMap<JobParameters,java.util.concurrent.ExecutorService> workers=new java.util.concurrent.ConcurrentHashMap<>();
 public static void schedule(Context c){JobScheduler jobs=c.getSystemService(JobScheduler.class);JobInfo.Builder b=new JobInfo.Builder(2312,new ComponentName(c,MobileSyncJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY);if(Build.VERSION.SDK_INT>=31)b.setExpedited(true);if(jobs.schedule(b.build())==JobScheduler.RESULT_FAILURE)jobs.schedule(new JobInfo.Builder(2312,new ComponentName(c,MobileSyncJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setBackoffCriteria(30000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build());}
 static void action(Context c,String callId,String action){android.os.PersistableBundle extras=new android.os.PersistableBundle();extras.putString("callId",callId);extras.putString("action",action);extras.putLong("generation",c.getSharedPreferences("communication-auth",0).getLong("generation",0));JobScheduler jobs=c.getSystemService(JobScheduler.class);JobInfo.Builder b=new JobInfo.Builder(2313,new ComponentName(c,MobileSyncJob.class)).setExtras(extras).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY);if(Build.VERSION.SDK_INT>=31)b.setExpedited(true);if(jobs.schedule(b.build())==JobScheduler.RESULT_FAILURE)jobs.schedule(new JobInfo.Builder(2313,new ComponentName(c,MobileSyncJob.class)).setExtras(extras).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setBackoffCriteria(30000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build());}
 @Override public boolean onStartJob(JobParameters p){java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();workers.put(p,worker);worker.execute(()->{boolean retry=false;try{String action=p.getExtras().getString("action","");if(action.equals("reject")||action.equals("end")){String id=p.getExtras().getString("callId","");if(!id.matches("[a-fA-F0-9-]{36}")||!MobileNativeApi.current(this,p.getExtras().getLong("generation")))return;DriverNativeApi.Result result=MobileNativeApi.request(this,"POST","calls/"+id+"/"+action,new org.json.JSONObject().put("deviceId",CommunicationNotifications.device(this)));retry=result.status>=500;}else MobileNativeApi.sync(this);}catch(Exception e){retry=true;}finally{if(workers.remove(p,worker))jobFinished(p,retry);worker.shutdown();}});return true;}
 @Override public boolean onStopJob(JobParameters p){java.util.concurrent.ExecutorService worker=workers.remove(p);if(worker!=null)worker.shutdownNow();return true;}
}
